// ดึง output จาก Editor Agent
const editorRaw = $('Editor Agent1').first().json;
const rawText = editorRaw.output?.[0]?.content?.[0]?.text || editorRaw.message?.content || '';
const cleaned = rawText.replace(/^```json\n?/i,'').replace(/^```\n?/i,'').replace(/\n?```$/i,'').trim();

let editorResult = {};
try { editorResult = JSON.parse(cleaned); } catch(e) { editorResult = { content: cleaned }; }

const htmlContent = editorResult.content || cleaned;
const rating = editorResult.rating || null;
const scoreBreakdown = editorResult.scoreBreakdown || null;
const pros = Array.isArray(editorResult.pros) ? editorResult.pros : [];
const cons = Array.isArray(editorResult.cons) ? editorResult.cons : [];

// ดึงข้อมูลจาก Sheet
const sheet = $('เตรียมข้อมูล').first().json;
const productName = (sheet['product_name'] || '').replace(/^=+/, '').trim();
const price = String(sheet['price'] || '').replace(/^=+/, '').trim();
const affiliateUrl = sheet['affiliate_url'] || '';
const categoryName = sheet['category'] || 'ทั่วไป';
const myjakkitUrl = (categoryName.includes('หนังสือ') && sheet['myjakkit_url']) ? String(sheet['myjakkit_url']).trim() : null;

// ดึง Video URL — Cloudinary ถาวรก่อน, fallback ไป kie.ai/Veo 3 (ใช้ .last() เพื่อเอา poll รอบที่วิดีโอเสร็จ)
let videoUrl = null;
try {
  const cloudinaryResp = $('Upload Video Cloudinary1').last().json;
  videoUrl = cloudinaryResp?.secure_url || null;
} catch(e) { console.log('Cloudinary resp error:', e.message); }

if (!videoUrl) {
  try {
    const d = $('เช็คสถานะ Veo ').last().json?.data || {};
    videoUrl = d?.response?.resultUrls?.[0]
      || d?.resultUrls?.[0]
      || d?.response?.resultUrl
      || d?.resultUrl
      || null;
    if (!videoUrl && d?.response?.resultJson) {
      try { const rj = JSON.parse(d.response.resultJson); videoUrl = rj?.resultUrls?.[0] || rj?.resultUrl || null; } catch(e) {}
    }
    if (!videoUrl) console.log('ไม่พบ Video URL ใน Veo response:', JSON.stringify(d).substring(0, 500));
  } catch(e) { console.log('Veo resp error:', e.message); }
}

if (videoUrl) console.log('Video URL:', videoUrl);

// ดึงรูปจาก Cloudinary
const img1 = $('แปลงรูป Cloudinary1').first().json?.secure_url || '';
const img2 = $('แปลงรูป Cloudinary4').first().json?.secure_url || '';
const img3 = $('แปลงรูป Cloudinary5').first().json?.secure_url || '';
const images = [img1, img2, img3].filter(Boolean);

const baseSlug = productName.toLowerCase().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').substring(0,60);
const slug = (baseSlug || 'article') + '-' + Date.now();

const title = editorResult.title || `รีวิว ${productName}${price ? ' ราคา ' + price + ' บาท' : ''}`;
const excerpt = `รีวิวครบ ${productName} พร้อมข้อดี-ข้อเสีย คะแนน ${rating ? rating.toFixed(1) : '?'}/5 และความคุ้มค่าราคา`;

return [{
  json: {
    title, slug, excerpt,
    content: htmlContent,
    featuredImage: images[0] || null,
    images,
    rating, scoreBreakdown,
    pros,
    cons,
    affiliateUrl,
    price: String(price),
    productName,
    categoryName,
    categorySlug: categoryName.toLowerCase().replace(/\s+/g,'-'),
    videoUrl: videoUrl || null,
    myjakkitUrl,
    published: true
  }
}];

const serperData = $input.first().json;
const items = [
  ...(serperData.organic || []).slice(0, 5),
  ...(serperData.knowledgeGraph ? [{ title: serperData.knowledgeGraph.title, snippet: JSON.stringify(serperData.knowledgeGraph.attributes || {}), link: '' }] : [])
];
const specsContext = items.map(r => `- ${r.title || ''}: ${r.snippet || ''}`).join('\n').substring(0, 2000);
const productName = $('เตรียมข้อมูล').first().json['product_name'] || '';
return [{ json: { specsContext, productName } }];

