if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
if (body && typeof body === 'object' && body.title === undefined) {
  const k = Object.keys(body);
  if (k.length === 1 && String(k[0]).trim().startsWith('{')) { try { body = JSON.parse(k[0]); } catch (e) {} }
}
body = body || {};

const title = body.title || '';
const slug = body.slug || '';
